refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     min ora lancia un ValueError in caso di errore;
     in precedenza veniva restituito &false; e veniva emesso un errore E_WARNING.




    8.0.0

     Poiché i 
     confronti tra stringhe e numeri sono stati modificati,
     min non restituisce più un
     valore diverso in base all'ordine degli argomenti in questi casi.

  &reftitle.examples;



    Esempi di utilizzo di min


<?php
echo min(2, 3, 1, 6, 7), PHP_EOL;  // 1
echo min(array(2, 4, 5)), PHP_EOL; // 2

// 'ciao' è una stringa non numerica, quindi -1 viene convertito nella stringa "-1" e i
// valori vengono confrontati come stringhe: "-1" è minore di "ciao"
echo min('ciao', -1), PHP_EOL;    // -1

// Con più array di lunghezze diverse, min restituisce il più corto
$val = min(array(2, 2, 2), array(1, 1, 1, 1)); // array(2, 2, 2)
var_dump($val);

// Più array della stessa lunghezza vengono confrontati da sinistra a destra
// quindi nell'esempio: 2 == 2, ma 4 < 5
$val = min(array(2, 4, 8), array(2, 5, 1)); // array(2, 4, 8)
var_dump($val);

// Se vengono forniti sia un array sia un non-array, l'array non viene mai restituito
// poiché i confronti considerano gli array maggiori di qualsiasi altro valore
// Tra i valori rimanenti, 42 viene convertito nella stringa "42" quando viene confrontato con la
// stringa non numerica 'stringa', e "42" è minore di "stringa"
$val = min('stringa', array(2, 5, 7), 42);   // 42
var_dump($val);

// Se un argomento è NULL o un booleano, verrà confrontato con
// gli altri valori usando le regole FALSE < TRUE e NULL == FALSE indipendentemente dagli
// altri tipi coinvolti
// Negli esempi seguenti, sia -10 che 10 vengono trattati come TRUE nel confronto
$val = min(-10, FALSE, 10); // FALSE
var_dump($val);

$val = min(-10, NULL, 10);  // NULL
var_dump($val);

// 0, invece, viene trattato come FALSE, quindi è "minore di" TRUE
$val = min(0, TRUE); // 0
var_dump($val);
?>
